'use client';
import React,{useState,useEffect,useRef,useMemo} from 'react';
import {Apple,Activity,ArrowDownRight,ArrowRight,ArrowUpRight,ArrowLeft,ArrowUp,BarChart3,Bell,BookOpen,CalendarDays,Check,CheckCircle2,ChevronDown,ChevronLeft,ChevronRight,Clock3,Cloud,CloudOff,Copy,Download,Dumbbell,FileText,Flame,Heart,HelpCircle,LayoutDashboard,Loader2,MessageCircle,MoreHorizontal,Pause,Play,Plus,RotateCcw,Send,Settings2,ShieldCheck,Sparkles,Target,TrendingUp,Upload,UserRound,Users,Volume2,VolumeX,X,Zap,Trash2,Edit3,ExternalLink,Expand,Grip,RefreshCw,Moon,Footprints,Flag} from 'lucide-react';
import baseJSON from '../lib/base-plan.json';
import {useStore} from '../lib/useStore';
import {Plan,Session,Profile,Store,Entry,Block,uid,today,localDate,dayDiff,addDays,weekOf,sessionDate,live,forProfile,context,readiness,markMeta,bestMark,doses,adaptSession,hRoutes,mRoutes,coachAdvice,coachReply,normalizePlan,bridgePrompt,mergeStores,validStore} from '../lib/engine';
import {extractFile,planFromText} from '../lib/documents';
import {ThemeSwitch,CompactHome,PlanDeck,SessionFlow,MoreHub} from './TouchUI';
import TimerStudio from './TimerStudio';
